const roles=['대장군','군주','태수','현령','북중랑장','기도위','의병 지휘자','의병','황건 수령','황건 장수','좌거기장군','우중랑장','별부사마','재야','포로'];
const tasks={개발:{days:5,cost:250},훈련:{days:3,cost:180},징병:{days:4,cost:500},군량:{days:3,cost:250}};
export function createGame(player='liubei'){
 if(!people.some(p=>p[0]===player))throw Error('선택할 수 없는 인물입니다.');
 const cities=citySeed.map((c,id)=>({id,name:c[0],faction:c[1],x:c[2],y:c[3],troops:c[4],governor:c[5],historicNote:c[6],gold:3000,food:18000,farm:45,training:45,morale:70,order:'균형',task:null}));
 return {version:VERSION,day:0,seed:184,player,people:people.map(p=>({id:p[0],name:p[1],faction:p[2],role:p[3],stats:p[4],ambition:p[5],loyalty:p[6],station:p[7],historicRole:p[8],goal:p[9],goalSince:0,lastAction:null,alive:true,merit:0,relations:{},extensions:{availableFrom:p[10]?.startsWith('unlock:')?Number(p[10].slice(7)):0}})),cities,armies:[],logs:[{day:0,text:'184년 3월, 황건의 난이 일어났습니다. 이 시나리오는 핵심 전선을 압축한 역사 기반 미니 캠페인입니다.'}],pending:null,nextArmy:1,extensions:{family:null},scenario:'184-historical-core'};
}
export const actor=s=>s.people.find(p=>p.id===s.player);
export const startingCity=s=>actor(s)?.station??0;
export const owned=(s,id)=>s.cities[id]?.faction===actor(s).faction;
export const personById=(s,id)=>s.people.find(p=>p.id===id);
export function authority(s,id){const p=actor(s),c=s.cities[id];if(!p?.alive||!c||c.faction!==p.faction)return {level:'none',label:'권한 없음',detail:'다른 세력의 도시는 조작할 수 없습니다.'};if(p.role==='대장군')return {level:'command',label:'대장군 군령',detail:'한 조정군의 모든 도시와 부대에 군령을 내릴 수 있습니다.'};if(p.role==='군주'||p.role==='황건 수령')return c.governor===p.id?{level:'command',label:'세력 수장',detail:'직할 거점의 내정·위임·출진을 결정합니다.'}:{level:'none',label:'직할지 아님',detail:'다른 거점은 아직 직접 지휘할 수 없습니다.'};if(c.governor===p.id&&['태수','현령'].includes(p.role))return {level:'command',label:'지방관',detail:'부임한 도시의 내정·위임·출진을 결정합니다.'};if(p.station===id)return {level:'lead',label:'임지·부대 지휘',detail:'임지에서 내정 건의를 내고, 자신의 부대를 이끌 수 있습니다.'};return {level:'none',label:'관할 밖',detail:'이곳은 현재 임지나 직할지가 아닙니다.'};}
function rand(s){s.seed=(Math.imul(s.seed,1664525)+1013904223)>>>0;return s.seed/4294967296;}
function log(s,text){s.logs.unshift({day:s.day,text});s.logs=s.logs.slice(0,100);}
export function available(s){return s.people.filter(p=>p.alive&&p.id!==s.player);}
export function order(s,id,type){const c=s.cities[id],p=actor(s),a=authority(s,id);if(s.pending)throw Error('먼저 진행 중인 사건을 결정하세요.');if(!c||a.level==='none')throw Error('현재 관할이나 임지가 아닌 도시입니다.');if(c.task)throw Error('이미 명령을 수행하고 있습니다.');const t=tasks[type];if(!t)throw Error('알 수 없는 명령입니다.');if(c.gold<t.cost)throw Error('자금이 부족합니다.');c.gold-=t.cost;c.task={type,left:t.days,by:p.id};log(s,`${c.name}: ${type} ${a.level==='lead'?'건의가 채택되어 ':''}착수했습니다. (${t.days}일)`);}
export function setPolicy(s,id,policy){const c=s.cities[id],a=authority(s,id);if(!c||a.level!=='command')throw Error('도시 방침은 대장군·군주·지방관의 권한입니다.');if(!['균형','농업','군비'].includes(policy))throw Error('잘못된 방침입니다.');c.order=policy;log(s,`${c.name}에 ${policy} 방침을 전달했습니다.`);}
export function recruit(s,id,cityId){if(s.pending)throw Error('먼저 진행 중인 사건을 결정하세요.');const p=actor(s),q=personById(s,id),c=s.cities[cityId],right=authority(s,cityId);if(!q?.alive||q.faction!==2||s.day<(q.extensions?.availableFrom||0))throw Error('현재 등용할 수 있는 재야 인재가 아닙니다.');if(!c||right.level==='none'||c.faction!==p.faction)throw Error('권한이 있는 아군 도시에서만 인재를 등용할 수 있습니다.');if(c.gold<800)throw Error(`${c.name}의 자금이 부족합니다. 등용에는 자금 800이 필요합니다.`);if(s.people.filter(x=>x.alive&&x.faction===p.faction).length>=14)throw Error('세력 인재가 많아 당분간 더 등용할 수 없습니다.');c.gold-=800;const relation=p.relations[id]||0,chance=Math.min(.9,Math.max(.2,.28+p.stats[4]/200+relation/250-q.loyalty/500));if(rand(s)<chance){q.faction=p.faction;q.role=p.faction===1?'황건 장수':'의병';q.station=c.id;q.loyalty=Math.min(100,q.loyalty+8);q.goal=`${p.name} 세력에서 새 뜻을 펼침`;q.goalSince=s.day;p.merit+=12;p.relations[id]=Math.min(100,relation+12);q.relations[p.id]=p.relations[id];q.lastAction=`${c.name}에서 ${p.name}의 등용에 응함`;log(s,`${p.name}의 등용 성공: ${q.name}이 ${c.name}에서 ${factions[p.faction]}에 합류했습니다. (성공 가능성 ${Math.round(chance*100)}%)`);return true;}log(s,`${p.name}의 등용 실패: ${q.name}이 아직 출사를 미뤘습니다. 자금 800을 사용했습니다. (성공 가능성 ${Math.round(chance*100)}%)`);return false;}
export function appoint(s,id,cityId){if(s.pending)throw Error('먼저 진행 중인 사건을 결정하세요.');const p=actor(s),q=personById(s,id),c=s.cities[cityId],right=authority(s,cityId);if(!q?.alive||q.faction!==p.faction||q.id===p.id)throw Error('임명할 수 있는 소속 인물을 선택하세요.');if(!c||c.faction!==p.faction||right.level!=='command')throw Error('대장군·군주·지방관만 관할 도시의 인사를 임명할 수 있습니다.');if(c.governor)throw Error(`${c.name}에는 이미 책임자가 있습니다.`);if(q.role==='재야')throw Error('먼저 이 인물을 등용해야 합니다.');c.governor=q.id;q.role='태수';q.station=c.id;q.lastAction=`${c.name} 태수로 임명됨`;q.goal=`${c.name}의 민심과 군정을 안정시킴`;q.goalSince=s.day;log(s,`${p.name}이 ${q.name}을 ${c.name} 태수로 임명했습니다.`);}
export function interact(s,id){if(s.pending)throw Error('먼저 진행 중인 사건을 결정하세요.');const p=actor(s),q=personById(s,id);if(!q?.alive||q.id===p.id)throw Error('교류할 수 없는 인물입니다.');if(q.faction!==p.faction)throw Error('현재는 같은 세력 인물과만 교류할 수 있습니다.');if(p.lastTalk===s.day)throw Error('오늘은 이미 교류했습니다. 하루를 진행하세요.');if(q.station!==p.station)throw Error('같은 주둔지의 인물과만 교류할 수 있습니다.');p.lastTalk=s.day;p.relations[id]=Math.min(100,(p.relations[id]||0)+8);q.relations[p.id]=p.relations[id];p.merit+=2;log(s,`${q.name}와 ${s.cities[p.station]?.name||p.historicRole}에서 군정에 관해 이야기했습니다. 상호 친밀도 ${p.relations[id]}.`);}
export function march(s,from,to,count=2000,tactic='신중',unit='보병'){if(s.pending)throw Error('먼저 진행 중인 사건을 결정하세요.');const p=actor(s),a=s.cities[from],b=s.cities[to],right=authority(s,from);if(!a||!b||right.level==='none'||a.faction===b.faction)throw Error('권한이 있는 아군 도시에서 적 도시로 출진하세요.');if(right.level==='lead'&&p.station!==from)throw Error('장수는 임지에서만 출진할 수 있습니다.');if(!roads.some(r=>r.includes(from)&&r.includes(to)))throw Error('연결된 도시로만 출진할 수 있습니다.');if(!['신중','강습','포위'].includes(tactic)||!['보병','기병','궁병'].includes(unit))throw Error('잘못된 편성입니다.');if(!Number.isInteger(count)||count<1000||count>a.troops-1000)throw Error('출진 1,000명 이상, 수비병 1,000명 이상이 필요합니다.');const food=Math.ceil(count*.7);if(a.food<food)throw Error('원정 군량이 부족합니다.');if(s.armies.some(x=>x.leader===p.id))throw Error('지휘 중인 부대가 귀환한 뒤 출진하세요.');a.troops-=count;a.food-=food;const duration=Math.max(2,Math.ceil(Math.hypot(a.x-b.x,a.y-b.y)/(unit==='기병'?65:45)))+(tactic==='포위'?2:0);s.armies.push({id:s.nextArmy++,from,to,faction:p.faction,troops:count,food,days:duration,total:duration,tactic,unit,training:a.training,morale:a.morale,leader:p.id});log(s,`${p.name}: ${a.name} → ${b.name}, ${unit} ${count.toLocaleString()}명 출진. 도착까지 ${duration}일.`);}
function battle(s,a){const c=s.cities[a.to],p=personById(s,a.leader),supplied=s.cities[a.from].faction===a.faction;if(c.faction===a.faction){c.troops+=a.troops;log(s,`${c.name}에 증원군이 합류했습니다.`);return;}const terrain=(c.id===3||c.id===4)?'험지':'평지',unitFactor=a.unit==='기병'?(terrain==='평지'?1.17:.82):a.unit==='궁병'?1.06:1,tactic=a.tactic==='강습'?1.14:a.tactic==='포위'?1.22:1,attack=a.troops*(.6+p.stats[0]/100)*(1+a.training/140)*(a.morale/70)*unitFactor*tactic*(supplied?1:.65)*(.9+rand(s)*.2),defense=c.troops*1.35*(1+c.training/160)*(c.morale/70)*(terrain==='험지'?1.15:1),win=attack>defense,loss=win?.25:a.tactic==='강습'?.6:.4,survivors=Math.floor(a.troops*(1-loss));if(win){c.faction=a.faction;c.troops=survivors;c.morale=55;c.governor=null;p.merit+=40;}else{c.troops=Math.max(300,Math.floor(c.troops*.77));const home=s.cities[a.from].faction===a.faction?s.cities[a.from]:s.cities.find(x=>x.faction===a.faction);if(home)home.troops+=survivors;p.merit+=5;}const text=`${c.name} ${win?'함락':'공략 실패'}. 아군 ${a.troops-survivors}명 손실. ${terrain} · ${a.unit} · 훈련 ${a.training} · ${a.tactic} · 보급 ${supplied?'유지':'단절'}. 전력비 ${(attack/defense).toFixed(2)}.`;s.pending={kind:'report',title:win?'승전 보고':'퇴각 보고',text};log(s,text);}
function appointmentTarget(s,p){return s.cities.find(c=>c.faction===p.faction&&!c.governor);}
function aiHome(s,p){if(s.cities[p.station]?.faction===p.faction)return s.cities[p.station];return s.cities.find(c=>c.governor===p.id&&c.faction===p.faction)||s.cities.find(c=>c.governor&&personById(s,c.governor)?.faction===p.faction)||s.cities.find(c=>c.faction===p.faction);}
function updateGoal(s,p,front){let goal=p.id==='caocao'?'토벌군 선봉으로 전선 장악':p.id==='liubei'?'의병을 지키며 향리 민심 확보':p.id==='luzhi'?'거록 전선의 보급과 방어':p.id==='hejin'?'조정의 질서 유지와 군령 집행':p.id==='guan'?'유비를 지원하고 의병 전투력 보강':p.faction===1?'황건 봉기 세력의 거점 보전':'한 조정군의 전선 유지';if(front&&front.troops>7000)goal=p.faction===0?'전선 보강과 군량 확보':'강한 토벌군을 유인해 거점 방어';if(!front)goal=p.faction===0?'인근 거점의 질서와 보급 회복':'남은 황건 거점의 안전 확보';if(goal!==p.goal){const prior=p.goal;p.goal=goal;p.goalSince=s.day;log(s,`${p.name}의 목표 변화: ${prior} → ${goal}.`);}}
function aiIssueOrder(s,p,c,type){const q=tasks[type];if(!q||c.task||c.gold<q.cost)return false;c.gold-=q.cost;c.task={type,left:q.days,by:p.id};p.lastAction=`${c.name} ${type}`;log(s,`${p.name}(${p.role})의 자율 행동: ${c.name}에서 ${type} 명령. (${q.days}일)`);return true;}
function aiLaunch(s,p,from,to){if(!from||!to||from.troops<6200||from.food<6000||s.armies.some(a=>a.leader===p.id))return false;const count=Math.min(Math.floor((from.troops-1800)*.5/500)*500,Math.floor(from.food/1.4/500)*500);if(count<1500)return false;const unit='보병',tactic=p.ambition>85?'강습':'신중',food=Math.ceil(count*.7),duration=Math.max(2,Math.ceil(Math.hypot(from.x-to.x,from.y-to.y)/45));from.troops-=count;from.food-=food;s.armies.push({id:s.nextArmy++,from:from.id,to:to.id,faction:p.faction,troops:count,food,days:duration,total:duration,tactic,unit,training:from.training,morale:from.morale,leader:p.id,autonomous:true});p.lastAction=`${from.name}에서 ${to.name}으로 출진`;log(s,`${p.name}의 자율 군령: ${from.name}에서 ${to.name}(으)로 보병 ${fmtNum(count)}명 출진. 목표는 “${p.goal}”.`);return true;}
function fmtNum(n){return Math.floor(n).toLocaleString('ko-KR');}
function recruitForFaction(s,faction,leader){const candidates=s.people.filter(q=>q.alive&&q.faction===2&&s.day>=(q.extensions?.availableFrom||0)).sort((a,b)=>b.stats[4]-a.stats[4]);for(const q of candidates){const host=s.cities.find(c=>c.faction===faction&&c.gold>=800&&(c.governor===leader.id||c.id===leader.station));if(!host)break;const chance=Math.min(.82,.20+leader.stats[4]/220+leader.ambition/500-q.loyalty/520);if(rand(s)<chance){host.gold-=800;q.faction=faction;q.role=faction===1?'황건 장수':'의병';q.station=host.id;q.goal=`${leader.name} 세력에서 새 뜻을 펼침`;q.goalSince=s.day;q.lastAction=`${host.name}에서 ${leader.name}의 등용에 응함`;leader.merit+=8;log(s,`${leader.name}이 재야 인재 ${q.name}을 등용해 ${host.name}에 배치했습니다.`);return true;}log(s,`${leader.name}이 ${q.name}에게 출사를 권했으나 거절당했습니다.`);}return false;}
function appointVacancies(s,faction){const c=s.cities.find(x=>x.id>=8&&x.faction===faction&&!x.governor);if(!c)return;const q=s.people.filter(p=>p.alive&&p.faction===faction&&p.id!==s.player&&!['군주','황건 수령','대장군'].includes(p.role)&&s.cities[p.station]?.governor!==p.id).sort((a,b)=>b.stats[3]-a.stats[3])[0];if(q){c.governor=q.id;q.role='태수';q.station=c.id;q.goal=`${c.name}의 민심과 군정을 안정시킴`;q.goalSince=s.day;q.lastAction=`${c.name} 태수로 부임`;log(s,`${q.name}이 ${c.name} 태수로 부임해 도시를 맡았습니다.`);}}
function thinkFaction(s,faction){appointVacancies(s,faction);const officers=s.people.filter(p=>p.alive&&p.faction===faction&&p.id!==s.player&&['대장군','군주','태수','현령','북중랑장','기도위','의병 지휘자','의병','황건 수령','황건 장수'].includes(p.role)).sort((a,b)=>b.ambition-a.ambition);if(!officers.length)return;for(const p of officers){if(s.day>=30&&s.day%28===0&&recruitForFaction(s,faction,p))continue;const home=aiHome(s,p);if(!home)continue;const fronts=s.cities.filter(c=>c.faction!==faction&&roads.some(r=>r.includes(home.id)&&r.includes(c.id))).sort((a,b)=>b.troops-a.troops),front=fronts[0];updateGoal(s,p,front);if(front&&home.troops>=6200&&home.food>=6000&&!s.armies.some(a=>a.leader===p.id)){const urgency=front.troops>home.troops*1.25?.32:.58;if(rand(s)<urgency&&aiLaunch(s,p,home,front))continue;}if(home.task)continue;const frontline=front&&home.troops<front.troops*.85;const type=home.food<6500?'군량':home.troops<4500?'징병':home.training<55?'훈련':home.order==='농업'?'개발':frontline?'징병':rand(s)<.38?'개발':'훈련';aiIssueOrder(s,p,home,type);}}
function weeklyWorld(s){for(const faction of [0,1])thinkFaction(s,faction);}

function tick(s){s.day++;for(const c of s.cities){c.gold+=8+Math.floor(c.farm/10);c.food=Math.max(0,c.food+Math.floor(c.farm*2)-Math.ceil(c.troops*.006));if(c.food===0){c.morale=Math.max(10,c.morale-2);c.troops=Math.max(0,c.troops-20);}if(c.task&&--c.task.left<=0){const t=c.task,q=personById(s,t.by);if(t.type==='개발')c.farm=Math.min(100,c.farm+8);if(t.type==='훈련')c.training=Math.min(100,c.training+8);if(t.type==='징병')c.troops+=1000;if(t.type==='군량')c.food+=3500;if(q?.alive)q.merit+=8;log(s,`${c.name}: ${t.type} 완료.`);c.task=null;}if(s.day%7===0){if(c.order==='농업'&&c.gold>=80){c.gold-=80;c.farm=Math.min(100,c.farm+2);}if(c.order==='군비'&&c.gold>=100){c.gold-=100;c.troops+=200;c.training=Math.min(100,c.training+1);}}}if(s.day%7===0)weeklyWorld(s);for(const a of s.armies)a.days=Math.max(0,a.days-1);const due=s.armies.find(a=>a.days===0);if(due){s.armies=s.armies.filter(a=>a.id!==due.id);battle(s,due);}const p=actor(s),target=appointmentTarget(s,p);if(!s.pending&&p.faction===0&&['기도위','의병 지휘자','의병','북중랑장'].includes(p.role)&&p.merit>=30&&!p.promotionOffered&&target){p.promotionOffered=true;s.pending={kind:'promotion',title:'현령 임명 제안',text:`공적을 인정받아 ${target.name}의 현령으로 부임하라는 명을 받았습니다. 수락하면 그 도시의 방침과 출진을 직접 결정합니다.`,target:target.id};}if(!s.pending&&s.day>=15&&!s.historyEventRaised){s.historyEventRaised=true;s.pending={kind:'history',title:'황건 토벌 동원령',text:'황건 봉기가 확산되자 조정은 각지에 추가 동원을 명했습니다. 이는 184년의 정세를 바탕으로 재구성한 선택 사건입니다. 동원에 응하면 소속 도시 자금 300을 사용해 공적 10을 얻습니다.'};}}
export function advance(s,days){if(![1,7,30].includes(days))throw Error('1일·7일·30일만 진행할 수 있습니다.');if(s.pending)throw Error('진행 중인 사건부터 결정하세요.');let moved=0;while(moved<days&&!s.pending){tick(s);moved++;}return moved;}
export function resolve(s,choice='confirm'){const e=s.pending;if(!e)throw Error('진행 중인 사건이 없습니다.');if(!['confirm','accept','decline'].includes(choice))throw Error('잘못된 선택입니다.');if(e.kind==='promotion'&&choice==='accept'){const p=actor(s),c=s.cities[e.target];if(!c||c.governor)throw Error('임명할 도시가 없습니다.');p.role='현령';p.station=c.id;c.governor=p.id;log(s,`${p.name}, ${c.name} 현령에 임명되었습니다.`);}if(e.kind==='history'&&choice==='accept'){const c=s.cities.find(c=>c.faction===actor(s).faction&&c.gold>=300);if(!c)throw Error('소속 도시의 자금이 부족합니다.');c.gold-=300;actor(s).merit+=10;log(s,'추가 동원에 응했습니다. 공적 +10.');}s.pending=null;}
export function succeed(s,id){const q=personById(s,id);if(!q?.alive)throw Error('생존 인물을 선택하세요.');if(actor(s).alive)throw Error('사망 후에만 계승할 수 있습니다.');s.player=id;log(s,`${q.name}의 시점으로 이야기를 이어갑니다.`);}
function migrateV3(old){const fresh=createGame(old.player);fresh.day=old.day;fresh.seed=old.seed;for(const c of fresh.cities){const prior=old.cities?.find(x=>x.name===c.name);if(prior)for(const k of ['troops','gold','food','farm','training','morale','order','task','governor'])if(prior[k]!==undefined)c[k]=prior[k];}for(const p of fresh.people){const prior=old.people?.find(x=>x.id===p.id);if(prior)Object.assign(p,{merit:prior.merit||0,relations:prior.relations||{},alive:prior.alive!==false,station:prior.station??p.station,role:prior.role??p.role,goal:prior.goal??p.goal,goalSince:prior.goalSince||0,lastAction:prior.lastAction||null,loyalty:prior.loyalty??p.loyalty});}fresh.logs=[{day:fresh.day,text:'이전 v0.3 저장을 v0.4로 전환했습니다. 기존 진행과 인물을 유지하고 신규 거점·등용·임관 기능을 추가했습니다.'},...(old.logs||[]).slice(0,99)];return fresh;}
function migrateV2(old){const fresh=createGame(old.player);fresh.day=old.day;fresh.seed=old.seed;for(const c of fresh.cities){const prior=old.cities?.find(x=>x.name===c.name);if(prior)for(const k of ['troops','gold','food','farm','training','morale','order','task'])if(prior[k]!==undefined)c[k]=prior[k];}for(const p of fresh.people){const prior=old.people?.find(x=>x.id===p.id);if(prior){p.merit=prior.merit||0;p.relations=prior.relations||{};p.alive=prior.alive!==false;}}fresh.logs=[{day:fresh.day,text:'이전 저장을 NPC 자율 행동 v0.3으로 전환했습니다. 보유 자원과 날짜를 유지하고, 새 역사 시뮬레이션 규칙을 적용합니다.'},...(old.logs||[]).slice(0,99)];return fresh;}
function migrateV1(old){const fresh=createGame(old.player);for(const p of fresh.people){const legacy=old.people?.find(x=>x.id===p.id);if(legacy){p.merit=legacy.merit||0;p.relations=legacy.relations||{};p.alive=legacy.alive!==false;}}fresh.day=old.day||0;fresh.seed=old.seed||184;fresh.logs=[{day:fresh.day,text:'이전 v0.1 저장을 역사·권한 시스템 v0.3으로 전환했습니다. 기존 자원과 지도 진행은 새 캠페인으로 초기화되었습니다.'},...(old.logs||[]).slice(0,99)];return fresh;}
export function restore(raw){let s=JSON.parse(raw);if(s?.version===1&&s.scenario==='184-prototype')s=migrateV1(s);else if(s?.version===2&&s.scenario==='184-historical-core')s=migrateV2(s);else if(s?.version===3&&s.scenario==='184-historical-core')s=migrateV3(s);if(s?.version!==VERSION||s.scenario!=='184-historical-core'||!Number.isSafeInteger(s.day)||s.day<0||!Number.isInteger(s.seed)||s.seed<0||s.seed>4294967295)throw Error('지원하지 않거나 손상된 저장 파일입니다.');const base=createGame();if(!Array.isArray(s.cities)||s.cities.length!==base.cities.length||!Array.isArray(s.people)||s.people.length!==base.people.length||!Array.isArray(s.armies)||s.armies.length>100||!Array.isArray(s.logs)||s.logs.length>100)throw Error('저장 데이터 구성이 잘못되었습니다.');const num=(v,min=0,max=1e9)=>typeof v==='number'&&Number.isFinite(v)&&v>=min&&v<=max,str=v=>typeof v==='string'&&v.length<2000;for(let i=0;i<s.cities.length;i++){const c=s.cities[i],b=base.cities[i];if(c.id!==i||c.name!==b.name||c.x!==b.x||c.y!==b.y||![0,1].includes(c.faction)||!['균형','농업','군비'].includes(c.order)||!(c.governor===null||base.people.some(p=>p.id===c.governor))||!['troops','gold','food','farm','training','morale'].every(k=>num(c[k]))||c.farm>100||c.training>100||c.morale>100)throw Error('도시 데이터가 잘못되었습니다.');if(c.task&&(!Object.keys(tasks).includes(c.task.type)||!num(c.task.left,1,5)||!base.people.some(p=>p.id===c.task.by)))throw Error('명령 데이터가 잘못되었습니다.');}for(let i=0;i<s.people.length;i++){const p=s.people[i],b=base.people[i];if(p.id!==b.id||p.name!==b.name||![0,1,2].includes(p.faction)||!roles.includes(p.role)||typeof p.alive!=='boolean'||!num(p.merit)||typeof p.goal!=='string'||p.goal.length>120||!num(p.goalSince,0,s.day)||!Number.isInteger(p.station)||!s.cities[p.station]||!Array.isArray(p.stats)||p.stats.length!==5||!p.stats.every(v=>num(v,0,100))||!num(p.ambition,0,100)||!num(p.loyalty,0,100)||!p.relations||typeof p.relations!=='object'||!Object.entries(p.relations).every(([id,v])=>base.people.some(q=>q.id===id)&&num(v,0,100)))throw Error('인물 데이터가 잘못되었습니다.');}if(!actor(s)||!num(s.nextArmy,1)||!s.logs.every(l=>num(l.day)&&str(l.text)))throw Error('플레이어 또는 기록이 잘못되었습니다.');for(const a of s.armies)if(!num(a.id,1)||!s.cities[a.from]||!s.cities[a.to]||!roads.some(r=>r.includes(a.from)&&r.includes(a.to))||![0,1].includes(a.faction)||!num(a.troops)||!num(a.days,0,30)||!num(a.total,1,30)||!num(a.training,0,100)||!num(a.morale,0,100)||!['신중','강습','포위'].includes(a.tactic)||!['보병','기병','궁병'].includes(a.unit)||!s.people.some(p=>p.id===a.leader))throw Error('부대 데이터가 잘못되었습니다.');if(s.pending&&(!['history','promotion','report'].includes(s.pending.kind)||!str(s.pending.title)||!str(s.pending.text)||(s.pending.target!==undefined&&!s.cities[s.pending.target])))throw Error('사건 데이터가 잘못되었습니다.');return s;}
